import Foundation
import CryptoKit

// MARK: - Configuration
struct ServiceConfig {
    static let scriptDirectory = "/tmp/maintenance/"
    static let allowedOperations = ["backup", "cleanup", "rotate", "healthcheck"]
    static let maxTargetLength = 64
}

// MARK: - Script Templates
enum ScriptTemplate {
    static func backup(targets: [String]) -> String {
        var lines = ["#!/bin/bash", "set -euo pipefail", "BACKUP_DIR=/var/backups/$(date +%Y%m%d)"]
        lines.append("mkdir -p \"$BACKUP_DIR\"")
        for target in targets {
            lines.append("cp -r \(target) \"$BACKUP_DIR/\"")
        }
        lines.append("echo 'Backup complete'")
        return lines.joined(separator: "\n")
    }

    static func cleanup(targets: [String]) -> String {
        var lines = ["#!/bin/bash", "set -euo pipefail"]
        for target in targets {
            lines.append("find /tmp -name \(target) -mtime +7 -delete")
        }
        return lines.joined(separator: "\n")
    }

    static func rotate(targets: [String]) -> String {
        var lines = ["#!/bin/bash", "set -euo pipefail"]
        for target in targets {
            lines.append("logrotate -f /etc/logrotate.d/\(target)")
        }
        return lines.joined(separator: "\n")
    }

    static func healthcheck(targets: [String]) -> String {
        var lines = ["#!/bin/bash", "set -euo pipefail"]
        for target in targets {
            lines.append("systemctl is-active \(target) || echo \(target) is down")
        }
        return lines.joined(separator: "\n")
    }
}

// MARK: - Input Validation
struct InputValidator {
    private static let targetPattern = try! NSRegularExpression(pattern: "^[a-zA-Z0-9._-]+$")

    static func validateOperation(_ op: String) -> Bool {
        return ServiceConfig.allowedOperations.contains(op)
    }

    static func sanitizeTarget(_ target: String) -> String? {
        guard target.count <= ServiceConfig.maxTargetLength else { return nil }
        guard target.count > 0 else { return nil }
        let range = NSRange(target.startIndex..., in: target)
        guard targetPattern.firstMatch(in: target, range: range) != nil else { return nil }
        return target
    }

    static func sanitizeTargets(_ targets: [String]) -> [String] {
        return targets.compactMap { sanitizeTarget($0) }
    }
}

// MARK: - Script Manager
class ScriptManager {
    private let fileManager = FileManager.default

    init() {
        try? fileManager.createDirectory(atPath: ServiceConfig.scriptDirectory,
                                         withIntermediateDirectories: true)
    }

    func generateScript(operation: String, targets: [String]) -> String {
        switch operation {
        case "backup":    return ScriptTemplate.backup(targets: targets)
        case "cleanup":   return ScriptTemplate.cleanup(targets: targets)
        case "rotate":    return ScriptTemplate.rotate(targets: targets)
        case "healthcheck": return ScriptTemplate.healthcheck(targets: targets)
        default:          return "#!/bin/bash\nexit 1"
        }
    }

    func writeScript(content: String, identifier: String) throws -> String {
        let sanitizedId = identifier.replacingOccurrences(of: "/", with: "_")
                                     .replacingOccurrences(of: "..", with: "_")
        let path = ServiceConfig.scriptDirectory + sanitizedId + ".sh"
        try content.write(toFile: path, atomically: true, encoding: .utf8)
        try fileManager.setAttributes([.posixPermissions: 0o755], ofItemAtPath: path)
        return path
    }

    func executeScript(atPath path: String) throws -> String {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/bin/bash")
        process.arguments = [path]

        let pipe = Pipe()
        process.standardOutput = pipe
        process.standardError = pipe

        try process.run()
        process.waitUntilExit()

        let data = pipe.fileHandleForReading.readDataToEndOfFile()
        return String(data: data, encoding: .utf8) ?? ""
    }
}

// MARK: - Task Processing
struct MaintenanceTask {
    let operation: String
    let targets: [String]
    let requestId: String
}

class TaskProcessor {
    private let scriptManager = ScriptManager()
    private let queue = DispatchQueue(label: "task.processor", attributes: .concurrent)

    func processTask(_ task: MaintenanceTask) -> Result<String, Error> {
        // Validate operation
        guard InputValidator.validateOperation(task.operation) else {
            return .failure(NSError(domain: "InvalidOp", code: 400))
        }

        // Sanitize targets
        let cleanTargets = InputValidator.sanitizeTargets(task.targets)
        guard !cleanTargets.isEmpty else {
            return .failure(NSError(domain: "NoValidTargets", code: 400))
        }

        // Generate and execute script
        let scriptContent = scriptManager.generateScript(operation: task.operation, targets: cleanTargets)

        do {
            let scriptPath = try scriptManager.writeScript(content: scriptContent, identifier: task.requestId)
            let output = try scriptManager.executeScript(atPath: scriptPath)

            // Cleanup
            try? FileManager.default.removeItem(atPath: scriptPath)

            return .success(output)
        } catch {
            return .failure(error)
        }
    }
}

// MARK: - Message Handler
class MessageHandler {
    private let processor = TaskProcessor()
    private let symmetricKey: SymmetricKey

    init(keyData: Data) {
        self.symmetricKey = SymmetricKey(data: keyData)
    }

    func handleMessage(_ encryptedData: Data) -> String {
        guard let decrypted = decrypt(encryptedData) else {
            return "{\"error\": \"decryption_failed\"}"
        }

        guard let json = try? JSONSerialization.jsonObject(with: decrypted) as? [String: Any],
              let operation = json["op"] as? String,
              let targets = json["targets"] as? [String],
              let requestId = json["id"] as? String else {
            return "{\"error\": \"invalid_payload\"}"
        }

        let task = MaintenanceTask(operation: operation, targets: targets, requestId: requestId)
        let result = processor.processTask(task)

        switch result {
        case .success(let output): return "{\"status\": \"ok\", \"output\": \"\(output)\"}"
        case .failure(let error): return "{\"error\": \"\(error.localizedDescription)\"}"
        }
    }

    private func decrypt(_ data: Data) -> Data? {
        guard data.count > 12 else { return nil }
        let nonce = data.prefix(12)
        let ciphertext = data.dropFirst(12)
        guard let sealedBox = try? AES.GCM.SealedBox(nonce: AES.GCM.Nonce(data: nonce),
                                                      ciphertext: ciphertext.dropLast(16),
                                                      tag: ciphertext.suffix(16)),
              let plaintext = try? AES.GCM.open(sealedBox, using: symmetricKey) else {
            return nil
        }
        return plaintext
    }
}
